/* ==========================================================================
   日本の地理クイズアプリ - グローバルスタイル & テーマ定義
   ========================================================================== */

:root {
  --color-primary: #1e50a2; /* 瑠璃色 / インディゴブルー */
  --color-primary-light: #e8f0fe;
  --color-primary-dark: #123773;
  --color-accent: #00a381; /* 花緑青 / エメラルドグリーン */
  --color-accent-light: #e6f6f2;

  --color-success: #1b813e; /* 常磐色 / 正解グリーン */
  --color-success-bg: #eaf6ee;
  --color-success-border: #8fd0a3;

  --color-danger: #c93a40; /* 紅緋 / 不正解レッド */
  --color-danger-bg: #fdf0f0;
  --color-danger-border: #f1aeb1;

  --color-bg-app: #f4f7f6;
  --color-card-bg: #ffffff;
  --color-text-main: #2b333e;
  --color-text-muted: #64748b;
  --color-border: #e2e8f0;

  --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 6px 16px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 12px 28px rgba(30, 80, 162, 0.12);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;

  --font-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Hiragino Kaku Gothic ProN", "BIZ UDPGothic", Meiryo, sans-serif;
  --transition: all 0.22s cubic-bezier(0.4, 0, 0.2, 1);
}

/* リセット & 基本設定 */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-base);
  background-color: var(--color-bg-app);
  color: var(--color-text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
  padding: 1.5rem 1rem 3rem;
}

/* メインコンテナ */
.quiz-app {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* ヘッダーエリア */
.quiz-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0;
}

.quiz-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  background-color: var(--color-primary-light);
  color: var(--color-primary);
  font-size: 0.825rem;
  font-weight: 700;
  padding: 0.25rem 0.85rem;
  border-radius: var(--radius-full);
  letter-spacing: 0.05em;
}

.quiz-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

.quiz-subtitle {
  font-size: 0.925rem;
  color: var(--color-text-muted);
}

/* プログレスバー */
.progress-container {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  width: 100%;
  background: #ffffff;
  padding: 0.85rem 1.25rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
}

.progress-text {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-muted);
}

.progress-bar-track {
  width: 100%;
  height: 8px;
  background-color: #eef2f6;
  border-radius: var(--radius-full);
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--color-primary) 0%, var(--color-accent) 100%);
  border-radius: var(--radius-full);
  transition: width 0.35s ease;
}

/* カード基底スタイル */
.card {
  background-color: var(--color-card-bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  border: 1px solid var(--color-border);
  padding: 1.75rem;
  position: relative;
  overflow: hidden;
}

/* クイズカード */
.question-card {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  animation: fadeIn 0.3s ease-out;
}

.question-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px dashed var(--color-border);
  padding-bottom: 0.75rem;
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--color-primary);
}

.question-text {
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.55;
  color: var(--color-text-main);
}

/* 4択グリッド */
.options-grid {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* 選択肢ボタン */
.option-btn {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  width: 100%;
  min-height: 52px;
  padding: 0.95rem 1.15rem;
  background-color: #ffffff;
  border: 2px solid #e2e8f0;
  border-radius: var(--radius-md);
  color: var(--color-text-main);
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: var(--transition);
  position: relative;
  outline: none;
}

.option-btn:hover:not(.disabled) {
  border-color: var(--color-primary);
  background-color: var(--color-primary-light);
  transform: translateY(-1px);
}

.option-prefix {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 28px;
  border-radius: var(--radius-full);
  background-color: #f1f5f9;
  color: var(--color-text-muted);
  font-size: 0.875rem;
  font-weight: 700;
  flex-shrink: 0;
  transition: var(--transition);
}

.option-label {
  flex: 1;
}

/* 選択状態 */
.option-btn.selected {
  border-color: var(--color-primary);
  background-color: var(--color-primary-light);
}
.option-btn.selected .option-prefix {
  background-color: var(--color-primary);
  color: #ffffff;
}

/* 正解状態 */
.option-btn.correct {
  border-color: var(--color-success);
  background-color: var(--color-success-bg);
  color: var(--color-success);
}
.option-btn.correct .option-prefix {
  background-color: var(--color-success);
  color: #ffffff;
}

/* 不正解状態 */
.option-btn.incorrect {
  border-color: var(--color-danger);
  background-color: var(--color-danger-bg);
  color: var(--color-danger);
}
.option-btn.incorrect .option-prefix {
  background-color: var(--color-danger);
  color: #ffffff;
}

/* 無効化（回答後） */
.option-btn.disabled {
  cursor: default;
  opacity: 0.92;
}

/* 解説ボックス */
.explanation-box {
  background-color: #f8fafc;
  border-left: 4px solid var(--color-primary);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  padding: 1.15rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  animation: slideDown 0.25s ease-out;
}

.explanation-header {
  font-size: 0.925rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.explanation-text {
  font-size: 0.95rem;
  color: #334155;
  line-height: 1.6;
}

/* 次へ進むアクション */
.next-action-container {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.5rem;
}

/* ボタン汎用 */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 48px;
  padding: 0.85rem 1.75rem;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
  background-color: var(--color-primary);
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(30, 80, 162, 0.25);
}

.btn-primary:hover {
  background-color: var(--color-primary-dark);
  box-shadow: 0 6px 16px rgba(30, 80, 162, 0.35);
  transform: translateY(-2px);
}

.btn-primary:active {
  transform: translateY(0);
}

/* ==========================================================================
   結果表示画面 (ResultView)
   ========================================================================== */

.result-card {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  animation: fadeIn 0.35s ease-out;
}

.result-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

/* スコアサークル */
.score-circle {
  width: 140px;
  height: 140px;
  border-radius: var(--radius-full);
  background: radial-gradient(circle at 30% 30%, #ffffff 0%, #edf2f7 100%);
  border: 6px solid var(--color-primary);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
  margin-bottom: 0.5rem;
}

.score-number {
  font-size: 3rem;
  font-weight: 800;
  line-height: 1;
  color: var(--color-primary);
}

.score-total {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text-muted);
}

.score-label {
  font-size: 0.8rem;
  color: var(--color-text-muted);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.result-evaluation {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--color-text-main);
}

.result-summary-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text-main);
  border-left: 4px solid var(--color-accent);
  padding-left: 0.6rem;
  margin-bottom: 0.25rem;
}

/* 振り返りリスト */
.review-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.review-item {
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  padding: 1.25rem;
  background-color: #ffffff;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  transition: var(--transition);
}

.review-item.correct {
  border-left: 6px solid var(--color-success);
  background-color: rgba(27, 129, 62, 0.02);
}

.review-item.incorrect {
  border-left: 6px solid var(--color-danger);
  background-color: rgba(201, 58, 64, 0.02);
}

.review-q-num {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--color-text-muted);
}

.review-q-text {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--color-text-main);
  line-height: 1.45;
}

.review-answers {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  font-size: 0.9rem;
  background-color: #f8fafc;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
}

.review-user-ans {
  font-weight: 600;
}
.review-item.correct .review-user-ans {
  color: var(--color-success);
}
.review-item.incorrect .review-user-ans {
  color: var(--color-danger);
}

.review-correct-ans {
  font-weight: 700;
  color: var(--color-success);
}

.review-explanation {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  line-height: 1.55;
  border-top: 1px dashed var(--color-border);
  padding-top: 0.5rem;
}

/* リスタートコンテナ */
.restart-container {
  display: flex;
  justify-content: center;
  padding-top: 0.5rem;
}

.restart-container .btn-primary {
  width: 100%;
  max-width: 320px;
  min-height: 52px;
  padding: 1rem 2rem;
  font-size: 1.1rem;
}

/* アニメーションキーフレーム */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* アクセシビリティ：動きの低減設定 */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* レスポンシブ対応 (480px以下) */
@media (max-width: 480px) {
  body {
    padding: 1rem 0.5rem 2rem;
  }

  .quiz-title {
    font-size: 1.4rem;
  }

  .card {
    padding: 1.25rem 1rem;
    border-radius: var(--radius-md);
  }

  .question-text {
    font-size: 1.1rem;
  }

  .option-btn {
    min-height: 48px;
    padding: 0.85rem 1rem;
    font-size: 0.95rem;
  }

  .btn-primary {
    min-height: 48px;
  }

  .score-circle {
    width: 120px;
    height: 120px;
  }

  .score-number {
    font-size: 2.5rem;
  }

  .review-item {
    padding: 1rem 0.85rem;
  }
}

export type Difficulty = 'easy' | 'normal' | 'hard';

export type QuizCategory = '自然' | '歴史' | '地形・水域' | '名所・建造物' | string;

export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  answerIndex: number;
  explanation: string;
  category?: QuizCategory;
  difficulty?: Difficulty;
}

export interface UserAnswer {
  questionId: number;
  selectedIndex: number;
  isCorrect: boolean;
}

export interface ResultItem {
  question: QuizQuestion;
  userAnswer?: UserAnswer;
  selectedIndex: number;
  isCorrect: boolean;
}

export interface QuizCardProps {
  question: QuizQuestion;
  questionNumber: number;
  totalQuestions: number;
  selectedAnswer: number | null;
  isAnswered: boolean;
  onSelectAnswer: (index: number) => void;
  onNext: () => void;
}

export interface ResultViewProps {
  score: number;
  totalQuestions: number;
  questions?: QuizQuestion[];
  userAnswers?: UserAnswer[];
  results?: ResultItem[];
  onRestart: () => void;
}

import { QuizQuestion } from './types';

export const quizQuestions: QuizQuestion[] = [
  {
    id: 1,
    question: "日本で最も面積が広い都道府県はどこでしょう？",
    options: ["岩手県", "福島県", "長野県", "北海道"],
    answerIndex: 3,
    explanation: "北海道の面積は約83,424平方キロメートルで、日本の総面積の約22%を占める日本最大の都道府県です。なお、2番目に広いのは岩手県です。",
    category: "地形・水域",
    difficulty: "easy"
  },
  {
    id: 2,
    question: "日本で一番長い川はどれでしょう？",
    options: ["信濃川（千曲川）", "利根川", "石狩川", "天竜川"],
    answerIndex: 0,
    explanation: "信濃川は全長約367km（長野県内では千曲川と呼ばれる）で日本一の長さを誇ります。ちなみに流域面積が日本一広いのは利根川です。",
    category: "地形・水域",
    difficulty: "normal"
  },
  {
    id: 3,
    question: "日本の最高峰「富士山」がまたがっている2つの県はどこでしょう？",
    options: [
      "静岡県と長野県",
      "静岡県と山梨県",
      "山梨県と神奈川県",
      "長野県と山梨県"
    ],
    answerIndex: 1,
    explanation: "標高3,776mの富士山は、静岡県と山梨県にまたがっています。山頂部には明確な県境が定められていないことでも知られています。",
    category: "自然",
    difficulty: "normal"
  },
  {
    id: 4,
    question: "日本で一番大きな湖である「琵琶湖」がある都道府県はどこでしょう？",
    options: ["京都府", "岐阜県", "滋賀県", "三重県"],
    answerIndex: 2,
    explanation: "琵琶湖は滋賀県に位置し、面積は約670平方キロメートルで滋賀県の面積のおよそ6分の1を占めています。",
