export const getRandomQuestions = (
  questions: QuizQuestion[] = quizQuestions,
  count: number = questions.length
): QuizQuestion[] => {
  const shuffled = [...questions];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled.slice(0, count);
};

import { FC, useEffect } from 'react';
import { QuizCardProps } from '../types';

const prefixes = ['A', 'B', 'C', 'D'];

const QuizCard: FC<QuizCardProps> = ({
  question,
  questionNumber,
  totalQuestions,
  selectedAnswer,
  isAnswered,
  onSelectAnswer,
  onNext,
}) => {
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (isAnswered) return;

      const num = parseInt(event.key, 10);
      if (num >= 1 && num <= question.options.length) {
        onSelectAnswer(num - 1);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isAnswered, onSelectAnswer, question.options.length]);

  const getButtonClass = (index: number): string => {
    if (!isAnswered) {
      return selectedAnswer === index ? 'option-btn selected' : 'option-btn';
    }

    if (index === question.answerIndex) {
      return 'option-btn correct disabled';
    }

    if (selectedAnswer === index && index !== question.answerIndex) {
      return 'option-btn incorrect disabled';
    }

    return 'option-btn disabled';
  };

  return (
    <div className="card question-card">
      <div className="question-meta">
        <span>第 {questionNumber} 問</span>
        <span>全 {totalQuestions} 問</span>
      </div>

      <div className="question-text">
        {question.question}
      </div>

      <div className="options-grid" role="group" aria-label="選択肢">
        {question.options.map((option, index) => (
          <button
            key={`${question.id}-${option}`}
            type="button"
            className={getButtonClass(index)}
            onClick={() => {
              if (!isAnswered) {
                onSelectAnswer(index);
              }
            }}
            disabled={isAnswered}
            aria-pressed={selectedAnswer === index}
          >
            <span className="option-prefix">{prefixes[index]}</span>
            <span className="option-label">{option}</span>
          </button>
        ))}
      </div>

      {isAnswered && (
        <>
          <div
            className="explanation-box"
            role="status"
            aria-live="polite"
          >
            <div className="explanation-header">
              {selectedAnswer === question.answerIndex ? '⭕ 正解！' : '❌ 不正解...'}
              <span>解説</span>
            </div>
            <p className="explanation-text">{question.explanation}</p>
          </div>

          <div className="next-action-container">
            <button
              type="button"
              className="btn-primary"
              onClick={onNext}
            >
              {questionNumber < totalQuestions ? '次の問題へ' : '結果を見る'}
            </button>
          </div>
        </>
      )}
    </div>
  );
};

export default QuizCard;

import { FC, useMemo, useEffect } from 'react';
import { ResultViewProps } from '../types';

const prefixes = ['A', 'B', 'C', 'D'];

const getOptionPrefix = (index: number): string => {
  return prefixes[index] || String.fromCharCode(65 + index);
};

const ResultView: FC<ResultViewProps> = ({
  score = 0,
  totalQuestions,
  questions = [],
  userAnswers = [],
  results,
  onRestart,
}) => {
  // Enterキーで再挑戦できるようにキーイベントを登録
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        onRestart();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [onRestart]);

  // questionsまたはresultsから問題リストを取得（防御的処理）
  const displayQuestions = useMemo(() => {
    if (questions && questions.length > 0) {
      return questions;
    }
    if (results && results.length > 0) {
      return results.map((r) => r.question);
    }
    return [];
  }, [questions, results]);

  const effectiveTotal = typeof totalQuestions === 'number'
    ? totalQuestions
    : displayQuestions.length;

  const answerMap = useMemo(() => {
    const map = new Map<number, { selectedIndex: number; isCorrect: boolean }>();

    if (userAnswers && userAnswers.length > 0) {
      userAnswers.forEach((ua) => {
        map.set(ua.questionId, {
          selectedIndex: ua.selectedIndex,
          isCorrect: ua.isCorrect,
        });
      });
    } else if (results && results.length > 0) {
      results.forEach((r) => {
        map.set(r.question.id, {
          selectedIndex: r.selectedIndex,
          isCorrect: r.isCorrect,
        });
      });
    }

    return map;
  }, [userAnswers, results]);

  const getEvaluationText = (correctCount: number, total: number): string => {
    if (total <= 0) return 'クイズ終了です！';

    const accuracy = correctCount / total;

    if (accuracy === 1) {
      return '全問正解！素晴らしい日本の地理マスターです！';
    }
    if (accuracy >= 0.8) {
      return '大変よくできました！日本の地理にとても詳しいですね！';
    }
    if (accuracy >= 0.6) {
      return '合格ライン突破！なかなかの知識をお持ちです！';
    }
    if (accuracy >= 0.2) {
      return 'あと一歩！見直しをして次回満点を目指しましょう！';
    }
    return '惜しい！もう一度チャレンジして地理の知識を深めましょう！';
  };

  return (
    <div className="card result-card" role="region" aria-label="クイズ結果">
      <div className="result-header">
        <div className="score-circle" aria-label={`スコア: ${score} / ${effectiveTotal}`}>
          <span className="score-number">{score}</span>
          <span className="score-total">/ {effectiveTotal}</span>
          <span className="score-label">正解</span>
        </div>
        <p className="result-evaluation">
          {getEvaluationText(score, effectiveTotal)}
        </p>
      </div>

      <div>
        <h3 className="result-summary-title">問題の振り返り</h3>
        <div className="review-list">
          {displayQuestions.map((question, index) => {
            const userAnswer = answerMap.get(question.id);
            const isCorrect = userAnswer ? userAnswer.isCorrect : false;
            const userSelectedIndex = userAnswer !== undefined ? userAnswer.selectedIndex : -1;
            const hasSelected = userSelectedIndex >= 0 && userSelectedIndex < question.options.length;

            return (
              <div
                key={question.id ?? index}
                className={isCorrect ? 'review-item correct' : 'review-item incorrect'}
              >
                <div className="review-q-num">第 {index + 1} 問</div>
                <div className="review-q-text">{question.question}</div>
                <div className="review-answers">
                  <div className="review-user-ans">
                    あなたの回答:{' '}
                    {hasSelected
                      ? `${getOptionPrefix(userSelectedIndex)}. ${question.options[userSelectedIndex]}`
                      : '未回答'}
                    {isCorrect ? ' (正解)' : ' (不正解)'}
                  </div>
                  {!isCorrect && (
                    <div className="review-correct-ans">
                      正解: {getOptionPrefix(question.answerIndex)}. {question.options[question.answerIndex]}
                    </div>
                  )}
                </div>
                <div className="review-explanation">
                  {question.explanation}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="restart-container">
        <button
          type="button"
          className="btn-primary"
          onClick={onRestart}
          autoFocus
        >
          もう一度挑戦する
        </button>
      </div>
    </div>
  );
};

export default ResultView;

import { FC, useReducer, useEffect, useCallback, useMemo } from 'react';
import { quizQuestions, getRandomQuestions } from './quizData';
import { QuizQuestion, UserAnswer, ResultItem } from './types';
import QuizCard from './components/QuizCard';
import ResultView from './components/ResultView';
import './index.css';

interface QuizState {
  questions: QuizQuestion[];
  currentIndex: number;
  selectedAnswer: number | null;
  isAnswered: boolean;
  userAnswers: UserAnswer[];
  isCompleted: boolean;
}

type QuizAction =
  | { type: 'SELECT_ANSWER'; index: number }
  | { type: 'NEXT_QUESTION' }
  | { type: 'RESTART' };

const initQuizState = (questions: QuizQuestion[] = quizQuestions): QuizState => ({
  questions: Array.isArray(questions) && questions.length > 0 ? questions : quizQuestions,
  currentIndex: 0,
  selectedAnswer: null,
  isAnswered: false,
  userAnswers: [],
  isCompleted: false,
});

const quizReducer = (state: QuizState, action: QuizAction): QuizState => {
  switch (action.type) {
    case 'SELECT_ANSWER': {
      if (state.isAnswered) return state;

      const currentQuestion = state.questions[state.currentIndex];
      if (!currentQuestion) return state;

      const isCorrect = action.index === currentQuestion.answerIndex;
      const newUserAnswer: UserAnswer = {
        questionId: currentQuestion.id,
        selectedIndex: action.index,
        isCorrect,
      };

      return {
        ...state,
        selectedAnswer: action.index,
        isAnswered: true,
        userAnswers: [...state.userAnswers, newUserAnswer],
      };
    }

    case 'NEXT_QUESTION': {
      const isLast = state.currentIndex + 1 >= state.questions.length;
      if (isLast) {
        return {
          ...state,
          isCompleted: true,
        };
      }
      return {
        ...state,
        currentIndex: state.currentIndex + 1,
        selectedAnswer: null,
        isAnswered: false,
      };
    }

    case 'RESTART': {
      return initQuizState(getRandomQuestions(quizQuestions));
    }

    default:
      return state;
  }
};

const App: FC = () => {
  const [state, dispatch] = useReducer(quizReducer, undefined, () => initQuizState(quizQuestions));

  const { questions, currentIndex, selectedAnswer, isAnswered, userAnswers, isCompleted } = state;
  const currentQuestion = questions[currentIndex] || questions[0];
  const totalQuestions = questions.length;

  const handleSelectAnswer = useCallback((index: number) => {
    dispatch({ type: 'SELECT_ANSWER', index });
  }, []);

  const handleNext = useCallback(() => {
    dispatch({ type: 'NEXT_QUESTION' });
  }, []);

  const handleRestart = useCallback(() => {
    dispatch({ type: 'RESTART' });
  }, []);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Enter' && isAnswered && !isCompleted) {
        event.preventDefault();
        handleNext();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isAnswered, isCompleted, handleNext]);

  const score = useMemo(() => {
    return userAnswers.filter((ua) => ua.isCorrect).length;
  }, [userAnswers]);

  const results: ResultItem[] = useMemo(() => {
    return questions.map((q) => {
      const ua = userAnswers.find((ans) => ans.questionId === q.id);
      return {
        question: q,
        userAnswer: ua,
        selectedIndex: ua !== undefined ? ua.selectedIndex : -1,
        isCorrect: ua !== undefined ? ua.isCorrect : false,
      };
    });
  }, [questions, userAnswers]);

  const progressPercent = totalQuestions > 0
    ? Math.round(((currentIndex + (isAnswered ? 1 : 0)) / totalQuestions) * 100)
    : 0;

  return (
    <div className="quiz-app">
      <header className="quiz-header">
        <span className="quiz-badge">地理クイズ</span>
        <h1 className="quiz-title">日本の地理クイズ</h1>
        <p className="quiz-subtitle">全5問に挑戦して日本の地理マスターを目指そう！</p>
      </header>

      {!isCompleted && (
        <div className="progress-container">
          <div className="progress-text">
            <span>進捗</span>
            <span>第 {currentIndex + 1} 問 / 全 {totalQuestions} 問</span>
          </div>
          <div
            className="progress-bar-track"
            role="progressbar"
            aria-valuenow={progressPercent}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-label="クイズの進捗状況"
          >
            <div
              className="progress-bar-fill"
              style={{ width: `${progressPercent}%` }}
            />
          </div>
        </div>
      )}

      {!isCompleted && currentQuestion ? (
        <QuizCard
          question={currentQuestion}
          questionNumber={currentIndex + 1}
          totalQuestions={totalQuestions}
          selectedAnswer={selectedAnswer}
          isAnswered={isAnswered}
          onSelectAnswer={handleSelectAnswer}
          onNext={handleNext}
        />
      ) : (
        <ResultView
          score={score}
          totalQuestions={totalQuestions}
          questions={questions}
          userAnswers={userAnswers}
          results={results}
          onRestart={handleRestart}
        />
      )}
    </div>
  );
};

export default App;
